blocks.code:
flowchart TD
  A["Recurrence T(n)"] --> B{"Es linear?"}
  B -- "No" --> X["Do not apply characteristic equation"]
  B -- "Yes" --> C{"Constant coefficients?"}
  C -- "No" --> X
  C -- "Yes" --> D{"Decreases by fixed subtraction?"}
  D -- "No, decreases by n/b" --> Y["Use Master Theorem, Recursion Tree, or a change of variable"]
  D -- "Yes" --> E{"Homogeneous?"}
  E -- "Yes" --> F["Apply characteristic polynomial directly"]
  E -- "No" --> G{"Manageable forcing term?"}
  G -- "Yes" --> H["Homogeneous solution + particular solution"]
  G -- "No" --> X
  F --> I["Solve roots"]
  H --> I
  I --> J["Apply initial conditions"]
  J --> K["Identify dominant root and conclude"]
